#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    // solve: given a non‐empty Vec<char>, produce a copy of exactly the same length
    // and with ans[i] == t[i] for all valid indices.
    pub fn solve(t: Vec<char>) -> Vec<char>
        requires
            // input is non‐empty
            t.len() >= 1,
        ensures
            // the result has the same length
            |res: Vec<char>| res.len() == t.len() 
                // and is pointwise equal to the input
                && forall(|i: usize| i < t.len() ==> res[i] == t[i]),
    {
        // ans will grow from length 0 up to t.len()
        let mut ans: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // Loop over the input; at each iteration we append t[i] to ans.
        while i < t.len()
            invariant
                // i never exceeds t.len()
                i <= t.len(),
                // the output built so far has length i
                ans.len() == i,
                // and for all j < i, ans[j] == t[j]
                forall(|j: usize| j < i ==> ans[j] == t[j]),
            // to prove termination, we use the strictly decreasing measure t.len() - i
            decreases t.len() - i,
        {
            ans.push(t[i]);
            i += 1;
        }

        // return the fully constructed vector
        ans
    }

}